DROP TEMPORARY TABLE IF EXISTS foto_semilla;
-- Con clave primaria: Aiven exige una en toda tabla (sql_require_primary_key), también en las temporales.
CREATE TEMPORARY TABLE foto_semilla (n INT NOT NULL, especie VARCHAR(10) NOT NULL, foto MEDIUMBLOB NOT NULL, PRIMARY KEY (n));
INSERT INTO foto_semilla (n, especie, foto) VALUES (101, 'PERRO', UNHEX(''));  -- perro2 (Nicolás Pinilla)
INSERT INTO foto_semilla (n, especie, foto) VALUES (102, 'GATO', UNHEX(''));  -- gato3 (Alexandre Boucey)
INSERT INTO foto_semilla (n, especie, foto) VALUES (103, 'PERRO', UNHEX(''));  -- perro4 (Victor G.)
INSERT INTO foto_semilla (n, especie, foto) VALUES (104, 'GATO', UNHEX(''));  -- gato4 (Paul Hanaoka)
INSERT INTO foto_semilla (n, especie, foto) VALUES (901, 'PERRO', UNHEX(''));  -- perro7 (Karsten Winegeart)
INSERT INTO foto_semilla (n, especie, foto) VALUES (902, 'GATO', UNHEX(''));  -- gato2 (Mert Ceyhan)
INSERT INTO foto_semilla (n, especie, foto) VALUES (903, 'PERRO', UNHEX(''));  -- perro1 (Nail Gilfanov)
INSERT INTO foto_semilla (n, especie, foto) VALUES (904, 'GATO', UNHEX(''));  -- gato1 (Wietse Jongsma)

-- Solo a las que no tienen foto: nunca pisa una que alguien haya subido.
UPDATE mascota m JOIN foto_semilla f ON f.n = m.id
  SET m.foto = f.foto, m.foto_tipo = 'image/jpeg'
WHERE m.foto IS NULL;

DROP TEMPORARY TABLE IF EXISTS foto_semilla;
